Exception bigObjectEx = new BigObjectException('big object message');
System.assertEquals('big object message', bigObjectEx.getMessage());
System.assertEquals('System.BigObjectException', bigObjectEx.getTypeName());
System.assertEquals(0, bigObjectEx.getLineNumber());
System.assertEquals('', bigObjectEx.getStackTraceString());
System.assertEquals(0, bigObjectEx.getInaccessibleFields().size());
bigObjectEx.setMessage('changed big object');
System.assertEquals('changed big object', bigObjectEx.getMessage());
System.assertEquals(bigObjectEx, bigObjectEx.initCause(new DmlException('big object cause')));
System.assertEquals('big object cause', bigObjectEx.getCause().getMessage());
